import { __decorate } from "tslib";
import { Component } from "@angular/core";
import { ComboBox } from "../combobox.component";
import { DropdownList } from "carbon-components-angular/dropdown";
let DynamicListComboBox = class DynamicListComboBox {
    constructor() {
        this.items = [
            {
                content: "one"
            },
            {
                content: "two"
            },
            {
                content: "three"
            },
            {
                content: "four"
            }
        ];
    }
    updateSelected(event) {
        this.items.forEach((item) => {
            if (event.some(selectedItem => selectedItem.content === item.content)) {
                item.selected = true;
            }
            else {
                item.selected = false;
            }
        });
    }
    ngAfterViewInit() {
        setTimeout(() => {
            const newItems = JSON.parse(JSON.stringify(this.items));
            newItems.push({ content: `New ${newItems.length}` });
            this.items = newItems;
        }, 4000);
    }
};
DynamicListComboBox = __decorate([
    Component({
        selector: "app-dynamic-list-combobox",
        template: `
		<cds-combo-box
			[(items)]="items"
			itemValueKey="content"
			type="multi"
			(selected)="updateSelected($event)">
			<cds-dropdown-list></cds-dropdown-list>
		</cds-combo-box>
	`,
        imports: [ComboBox, DropdownList]
    })
], DynamicListComboBox);
export { DynamicListComboBox };
